import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        int n = sc.nextInt();
        char[] s = new char[n];
        for (int i = 0; i < n; i++) {
            s[i] = sc.next().charAt(0);
        }

        for (int len = 1; len <= n; len++) {
            if (check(s, n, len)) {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < len; i++) {
                    sb.append(s[i]);
                }
                System.out.println(sb.toString());
                return;
            }
        }
    }

    private static boolean check(char[] s, int n, int len) {
        char[] current = new char[len];
        System.arraycopy(s, 0, current, 0, len);
        int curLen = len;
        int idx = len;

        while (idx < n) {
            // Increment current
            int carry = 1;
            for (int i = curLen - 1; i >= 0 && carry > 0; i--) {
                int d = (current[i] - '0') + carry;
                if (d >= 10) {
                    current[i] = '0';
                    carry = 1;
                } else {
                    current[i] = (char) ('0' + d);
                    carry = 0;
                }
            }

            if (carry > 0) {
                char[] next = new char[curLen + 1];
                next[0] = '1';
                System.arraycopy(current, 0, next, 1, curLen);
                current = next;
                curLen++;
            }

            if (idx + curLen > n) {
                return false;
            }

            for (int i = 0; i < curLen; i++) {
                if (s[idx + i] != current[i]) {
                    return false;
                }
            }
            idx += curLen;
        }

        return idx == n;
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
